impl Solution{pub fn max_killed_enemies(g:Vec<Vec<char>>)->i32{if g.is_empty(){return 0}let(m,n)=(g.len(),g[0].len());let mut c=vec![0;n];let(mut row,mut b)=(0,0);for i in 0..m{for j in 0..n{if j==0||g[i][j-1]=='W'{row=0;let mut k=j;while k<n&&g[i][k]!='W'{if g[i][k]=='E'{row+=1}k+=1}}if i==0||g[i-1][j]=='W'{c[j]=0;let mut k=i;while k<m&&g[k][j]!='W'{if g[k][j]=='E'{c[j]+=1}k+=1}}if g[i][j]=='0'{b=b.max(row+c[j])}}}b}}
